import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';

const $=s=>document.querySelector(s), canvas=$('#world');
const palette=[{name:'Blue Coalition',color:0x42a9ce,edge:0x1b83a6},{name:'Ember Pact',color:0xe56d63,edge:0xb34443},{name:'Sunward Union',color:0xd9a543,edge:0xa97827},{name:'Violet League',color:0x9278d0,edge:0x674daa},{name:'Unclaimed',color:0xa8b9a2,edge:0x879a88}];
let renderer,scene,camera,raycaster,clock,tiles=[],selected=null,source=null,mode='normal',frame=0,elapsed=0,toastTimer,rotateAngle=0,zoom=1,drag=null,paused=false;
const grid={cols:18,rows:13}, landTotal=0, player={troops:640,gold:180}, factions=palette.slice(0,4).map((p,i)=>({id:i,name:p.name,troops:i?430:640,gold:i?180:180,alive:true}));
function seeded(a,b){let v=Math.sin(a*127.1+b*311.7+19.19)*43758.5453;return v-Math.floor(v)}
function init(){
  renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(canvas.clientWidth,canvas.clientHeight,false);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;
  scene=new THREE.Scene();scene.background=new THREE.Color('#bfd9d3');scene.fog=new THREE.Fog('#bfd9d3',22,45);
  camera=new THREE.OrthographicCamera(-10,10,7, -7,.1,100);camera.position.set(0,19,14);camera.lookAt(0,0,0);
  scene.add(new THREE.HemisphereLight(0xeaffef,0x597c70,2.1));const sun=new THREE.DirectionalLight(0xfff8dd,2.8);sun.position.set(-7,15,9);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-15;sun.shadow.camera.right=15;sun.shadow.camera.top=13;sun.shadow.camera.bottom=-13;sun.shadow.bias=-.0002;scene.add(sun);
  const sea=new THREE.Mesh(new THREE.PlaneGeometry(200,200),new THREE.MeshStandardMaterial({color:0xb7d4d0,roughness:.92}));sea.rotation.x=-Math.PI/2;sea.position.y=-.48;sea.receiveShadow=true;scene.add(sea);
  raycaster=new THREE.Raycaster();clock=new THREE.Clock();createMap();bind();render();requestAnimationFrame(loop);resize();
}
function createMap(){
  let id=0;const r=.62, centers=[];
  for(let row=0;row<grid.rows;row++)for(let col=0;col<grid.cols;col++){
    const x=(col-(grid.cols-1)/2)*Math.sqrt(3)*r+(row%2)*Math.sqrt(3)*r/2;
    const z=(row-(grid.rows-1)/2)*1.5*r;
    const dist=Math.sqrt((x/9.25)**2+(z/5.75)**2),edgeNoise=(seeded(col,row)-.5)*.16+Math.sin(col*.8+row*.43)*.035;
    if(dist>1+edgeNoise)continue;
    const h=.12+seeded(col+21,row+8)*.16+Math.max(0,1-dist)*.1;
    const cell={id:id++,col,row,x,z,h,owner:-1,garrison:Math.round(30+seeded(col+9,row+18)*43),city:false,mesh:null,line:null,decor:null};tiles.push(cell);centers.push([col,row]);
  }
  // Four small landing zones around a wide unclaimed frontier.
  const starts=[[2,6,0],[15,3,1],[15,9,2],[9,6,3]];
  starts.forEach(([sc,sr,owner])=>{let nearest=tiles.map(t=>({t,d:Math.hypot(t.col-sc,t.row-sr)})).filter(x=>x.d<1.38).sort((a,b)=>a.d-b.d);nearest.forEach(({t})=>{if(t.owner<0)t.owner=owner;t.garrison=owner===0?105:82});});
  const shape=new THREE.Shape();for(let i=0;i<6;i++){const a=Math.PI/6+i*Math.PI/3,px=Math.cos(a)*r,pz=Math.sin(a)*r;i===0?shape.moveTo(px,pz):shape.lineTo(px,pz)}shape.closePath();
  const geomBase=new THREE.ShapeGeometry(shape);geomBase.rotateX(-Math.PI/2);
  tiles.forEach(t=>{
    const geom=tileGeometry(t.x,t.z,r,t.h);
    const mat=[new THREE.MeshStandardMaterial({color:palette[t.owner<0?4:t.owner].color,roughness:.87,flatShading:true}),new THREE.MeshStandardMaterial({color:0x526d61,roughness:1,flatShading:true})];
    const mesh=new THREE.Mesh(geom,mat);mesh.position.y=0;mesh.castShadow=true;mesh.receiveShadow=true;mesh.userData.cell=t;scene.add(mesh);t.mesh=mesh;
    const pts=[];for(let i=0;i<6;i++){const a=Math.PI/6+i*Math.PI/3;pts.push(new THREE.Vector3(t.x+Math.cos(a)*r*.985,t.h+.012,t.z+Math.sin(a)*r*.985))}pts.push(pts[0].clone());const line=new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),new THREE.LineBasicMaterial({color:palette[t.owner<0?4:t.owner].edge,transparent:true,opacity:.8}));scene.add(line);t.line=line;
    if(seeded(t.col+91,t.row+53)>.88&&t.owner<0)addTrees(t);
  });
  const total=$('#territory-badge');total.textContent=`${tiles.length} REGIONS`;updateTerritories();
  selected=tiles.find(t=>t.owner===0);source=selected;updateSelected();
}
function tileGeometry(x,z,r,h){const verts=[],indices=[];const bottom=h-.23;for(let i=0;i<6;i++){const a=Math.PI/6+i*Math.PI/3;verts.push(x+Math.cos(a)*r,h,z+Math.sin(a)*r)}verts.push(x,h,z);for(let i=0;i<6;i++)indices.push(6,i,(i+1)%6);const base=verts.length/3;for(let i=0;i<6;i++){const a=Math.PI/6+i*Math.PI/3;verts.push(x+Math.cos(a)*r,bottom,z+Math.sin(a)*r)}for(let i=0;i<6;i++){const n=(i+1)%6;indices.push(i,base+i,base+n,i,base+n,n)}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));g.setIndex(indices);g.addGroup(0,18,0);g.addGroup(18,36,1);g.computeVertexNormals();return g}
function addTrees(t){const group=new THREE.Group();group.position.set(t.x,t.h+.02,t.z);for(let i=0;i<3;i++){const dx=(seeded(t.id,i)-.5)*.45,dz=(seeded(i,t.id+2)-.5)*.42,scale=.13+seeded(i+5,t.id)*.09;const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.025,.035,.15,5),new THREE.MeshStandardMaterial({color:0x826b4a}));trunk.position.set(dx,.075,dz);group.add(trunk);const top=new THREE.Mesh(new THREE.ConeGeometry(scale,.28+scale,5),new THREE.MeshStandardMaterial({color:i%2?0x5c946f:0x4d8167,flatShading:true}));top.position.set(dx,.23+scale*.25,dz);top.castShadow=true;group.add(top)}scene.add(group);t.decor=group}
function updateTile(t){const p=palette[t.owner<0?4:t.owner];t.mesh.material[0].color.setHex(p.color);t.line.material.color.setHex(p.edge);t.line.material.opacity=t.owner<0?.58:.9;if(t.decor&&t.owner>=0){scene.remove(t.decor);t.decor=null}if(t.city)createCity(t)}
function createCity(t){if(t.cityMesh)scene.remove(t.cityMesh);const g=new THREE.Group();g.position.set(t.x,t.h+.035,t.z);const stone=new THREE.MeshStandardMaterial({color:0xe9e5d1,roughness:.78}),roof=new THREE.MeshStandardMaterial({color:palette[t.owner<0?4:t.owner].edge,roughness:.7});for(let i=0;i<3;i++){const b=new THREE.Mesh(new THREE.BoxGeometry(.14,.11+i%2*.06,.14),i===1?roof:stone);b.position.set((i-1)*.14,.055+i%2*.02,(i%2-.5)*.12);b.castShadow=true;g.add(b)}const tower=new THREE.Mesh(new THREE.ConeGeometry(.1,.18,4),roof);tower.position.set(0,.22,0);tower.rotation.y=Math.PI/4;g.add(tower);scene.add(g);t.cityMesh=g}

