function createCity(t){if(t.cityMesh)scene.remove(t.cityMesh);const g=new THREE.Group();g.position.set(t.x,t.h+.035,t.z);const stone=new THREE.MeshStandardMaterial({color:0xe9e5d1,roughness:.78}),roof=new THREE.MeshStandardMaterial({color:palette[t.owner<0?4:t.owner].edge,roughness:.7});for(let i=0;i<3;i++){const b=new THREE.Mesh(new THREE.BoxGeometry(.14,.11+i%2*.06,.14),i===1?roof:stone);b.position.set((i-1)*.14,.055+i%2*.02,(i%2-.5)*.12);b.castShadow=true;g.add(b)}const tower=new THREE.Mesh(new THREE.ConeGeometry(.1,.18,4),roof);tower.position.set(0,.22,0);tower.rotation.y=Math.PI/4;g.add(tower);scene.add(g);t.cityMesh=g}

const ring=new THREE.Mesh(new THREE.RingGeometry(.62,.67,6),new THREE.MeshBasicMaterial({color:0xefffea,side:THREE.DoubleSide,transparent:true,opacity:.95}));ring.rotation.x=-Math.PI/2;ring.position.y=.2;ring.visible=false;scene.add(ring);
function neighbors(a,b){return Math.hypot(a.x-b.x,a.z-b.z)<1.17}
function updateSelected(){if(!selected)return;$('#selected-name').textContent=selected.owner===0?`Blue Coalition · ${selected.col+1}.${selected.row+1}`:selected.owner<0?'Unclaimed territory':palette[selected.owner].name;$('#selected-dot').style.background=selected.owner<0?'#a8b9a2':`#${palette[selected.owner].color.toString(16).padStart(6,'0')}`;$('#selected-force').textContent=Math.round(selected.garrison);$('#selected-city').textContent=selected.city?'City':'Outpost';$('#region-coord').textContent=`${String.fromCharCode(65+selected.col)}${selected.row+1}`;ring.visible=true;ring.position.set(selected.x,selected.h+.07,selected.z)}
function countOwner(owner){return tiles.filter(t=>t.owner===owner).length}
function updateTerritories(){const own=countOwner(0),pct=Math.floor(own/tiles.length*100);$('#land-count').textContent=own;$('#land-pct').textContent=pct+'%';$('#land-progress').style.width=pct+'%';$('#mission-pct').textContent=pct+'%';$('#mission-progress').style.width=pct+'%';$('#report-count').textContent=`${Math.max(1,feedCount)} REPORTS`;factions.forEach(f=>{const el=$(`#enemy-${f.id}`);if(el){const v=countOwner(f.id);el.querySelector('.enemy-bar i').style.width=`${Math.max(v?6:0,v/tiles.length*100*4)}%`;el.querySelector('.enemy-pct').textContent=v?`${Math.floor(v/tiles.length*100)}%`:'0%';if(!v)f.alive=false}})}
let feedCount=0;function report(icon,text){const list=$('#feed-list'),item=document.createElement('div');item.className='feed-item';item.innerHTML=`<span class="feed-icon">${icon}</span><span>${text}</span>`;list.prepend(item);while(list.children.length>4)list.lastChild.remove();feedCount++;$('#report-count').textContent=`${feedCount} REPORTS`}
function notify(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function isAdjacentOwner(target,owner){return tiles.some(t=>t.owner===owner&&neighbors(t,target))}
function startAttack(target,owner=0){const faction=factions[owner];if(!isAdjacentOwner(target,owner))return false;const power=Math.min(faction.troops,Math.max(owner===0?65:52,Math.round(faction.troops*(owner===0?.31:.24))));if(power<target.garrison+8)return false;faction.troops-=Math.round(target.garrison+power*.18);if(faction.troops<0)faction.troops=0;target.owner=owner;target.garrison=Math.max(16,Math.round(power-target.garrison));updateTile(target);if(owner===0){source=target;selected=target;updateSelected();report('⚑',`<strong>Territory secured.</strong> Blue Coalition advanced into the frontier.`);notify('Territory secured — keep expanding.')}else report('⚔',`<strong>${faction.name} expanded.</strong> A new border is forming.`);updateTerritories();return true}
function onTileClick(t){if(mode==='nuke'){
  if(t.owner<0||t.owner===0){notify('Select an enemy territory for the strike.');return}if(player.gold<260){notify('Insufficient gold — a strike costs ◈ 260.');return}
  player.gold-=260;const victim=t.owner;t.owner=-1;t.garrison=0;updateTile(t);tiles.filter(n=>n.owner===victim&&Math.hypot(n.x-t.x,n.z-t.z)<2.2).forEach(n=>{n.garrison=Math.max(15,Math.round(n.garrison*.48))});mode='normal';$('#nuke-btn').classList.remove('active');report('☢',`<strong>Nuclear strike!</strong> ${palette[victim].name} lost a frontier region.`);notify('Strike confirmed — territory neutralized.');updateSelected();updateTerritories();return;
  }
  if(mode==='city'){if(t.owner!==0){notify('Select one of your territories to build a city.');return}if(t.city){notify('This territory already has a city.');return}if(player.gold<120){notify('Insufficient gold — a city costs ◈ 120.');return}player.gold-=120;t.city=true;createCity(t);selected=t;mode='normal';$('#city-btn').classList.remove('active');updateSelected();report('⌂','<strong>City established.</strong> Production increased in this territory.');notify('City built — production boosted.');return}
  if(t.owner===0){selected=t;source=t;updateSelected();$('#instruction').innerHTML='<b>Border selected.</b> Tap any adjacent neutral or enemy region to attack.';return}
  const base=source&&source.owner===0?source:selected;if(base&&neighbors(base,t)){if(!startAttack(t,0)){notify(t.garrison>player.troops*.31?'Not enough troops to break this garrison.':'Attack failed — reinforce and try again.')}return}
  if(isAdjacentOwner(t,0)){if(!startAttack(t,0))notify('Enemy defenses are too strong for your available troops.');return}notify('Select one of your blue territories first.');
}
function toggleMode(which){if(mode===which){mode='normal';$('#city-btn').classList.remove('active');$('#nuke-btn').classList.remove('active');return}mode=which;$('#city-btn').classList.toggle('active',which==='city');$('#nuke-btn').classList.toggle('active',which==='nuke');notify(which==='city'?'Choose one of your territories for a city.':'Choose an enemy territory to target.');}
function aiTurn(){for(let owner=1;owner<4;owner++){const f=factions[owner];if(!f.alive||Math.random()>.8)continue;const frontier=tiles.filter(t=>t.owner!==owner&&isAdjacentOwner(t,owner)).sort(()=>Math.random()-.5);for(const target of frontier.slice(0,8)){if(startAttack(target,owner))break}}}
