function setZoom(next){zoom=THREE.MathUtils.clamp(next,.72,1.42);const aspect=canvas.clientWidth/Math.max(1,canvas.clientHeight),h=7.1/zoom;camera.left=-h*aspect;camera.right=h*aspect;camera.top=h;camera.bottom=-h;camera.updateProjectionMatrix();$('#zoom-label').textContent=`${Math.round(zoom*100)}%`}
