function render(){renderer.render(scene,camera)}
function loop(){requestAnimationFrame(loop);const dt=Math.min(clock.getDelta(),.06);if(!paused)tick(dt);if(selected){ring.rotation.z+=dt*.15;ring.position.y=selected.h+.065+Math.sin(elapsed*3)*.025}render()}
function bind(){
  $('#city-btn').addEventListener('click',()=>toggleMode('city'));$('#nuke-btn').addEventListener('click',()=>toggleMode('nuke'));
  $('#rotate-left').addEventListener('click',()=>{rotateAngle-=Math.PI/6;setCamera()});$('#rotate-right').addEventListener('click',()=>{rotateAngle+=Math.PI/6;setCamera()});$('#zoom-in').addEventListener('click',()=>setZoom(zoom*1.14));$('#zoom-out').addEventListener('click',()=>setZoom(zoom/1.14));$('#recenter').addEventListener('click',()=>{target.set(0,0,0);rotateAngle=0;setCamera();setZoom(1)});$('#restart').addEventListener('click',()=>location.reload());
  $('#enemy-list').innerHTML=factions.slice(1).map(f=>`<div class="enemy-row"><i class="enemy-dot" style="background:#${palette[f.id].color.toString(16)}"></i><span class="enemy-name">${f.name}</span><span class="enemy-bar"><i id="enemybar-${f.id}" style="background:#${palette[f.id].color.toString(16)};width:10%"></i></span><span class="enemy-pct" id="enemy-pct-${f.id}">0%</span></div>`).join('');
